 import React, { useState, useEffect } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'

export default function CommunityDetail() {
    const { id } = useParams()
    const { user, profile } = useAuth()
    const navigate = useNavigate()
    const [community, setCommunity] = useState(null)
    const [posts, setPosts] = useState([])
    const [isMember, setIsMember] = useState(false)
    const [isCreator, setIsCreator] = useState(false)
    const [loading, setLoading] = useState(true)
    const [showPaymentModal, setShowPaymentModal] = useState(false)
    const [newPost, setNewPost] = useState('')
    const [submitting, setSubmitting] = useState(false)
    const [debugInfo, setDebugInfo] = useState('')

    useEffect(() => {
        loadCommunityData()
    }, [id, user])

    const loadCommunityData = async () => {
        setLoading(true)
        setDebugInfo('Loading...')
        try {
            // 1. Load community details
            const { data: communityData, error: communityError } = await supabase
                .from('communities')
                .select(`
                    *,
                    profiles:creator_id (id, username, full_name, avatar_url)
                `)
                .eq('id', id)
                .single()

            if (communityError) {
                console.error('Community error:', communityError)
                setDebugInfo('Community error: ' + communityError.message)
                throw communityError
            }

            setCommunity(communityData)
            setIsCreator(user?.id === communityData?.creator_id)
            setDebugInfo('Community loaded')

            // 2. Check membership
            if (user) {
                const { data: memberData, error: memberError } = await supabase
                    .from('community_members')
                    .select('*')
                    .eq('community_id', id)
                    .eq('user_id', user.id)
                    .eq('status', 'active')
                    .maybeSingle()

                if (memberError) {
                    console.error('Member check error:', memberError)
                }
                setIsMember(!!memberData)
                setDebugInfo('Member: ' + (!!memberData))
            }

            // 3. Load posts - SIMPLE QUERY WITHOUT JOIN FIRST
            console.log('Loading posts for community:', id)
            
            // First, try a simple query without join
            const { data: postsData, error: postsError } = await supabase
                .from('community_posts')
                .select('*')
                .eq('community_id', id)
                .order('created_at', { ascending: false })

            if (postsError) {
                console.error('Posts error:', postsError)
                setDebugInfo('Posts error: ' + postsError.message)
                throw postsError
            }

            console.log('Raw posts data:', postsData)
            setDebugInfo('Posts count: ' + (postsData?.length || 0))

            // If we have posts, try to get profiles separately
            let postsWithProfiles = postsData || []
            if (postsData && postsData.length > 0) {
                // Get unique user IDs
                const userIds = [...new Set(postsData.map(p => p.user_id))]
                const { data: profilesData, error: profilesError } = await supabase
                    .from('profiles')
                    .select('id, username, full_name, avatar_url')
                    .in('id', userIds)

                if (!profilesError && profilesData) {
                    // Map profiles to posts
                    postsWithProfiles = postsData.map(post => ({
                        ...post,
                        profiles: profilesData.find(p => p.id === post.user_id)
                    }))
                }
            }

            setPosts(postsWithProfiles)
            setDebugInfo('Posts loaded: ' + postsWithProfiles.length)

            // 4. Load members count
            const { count } = await supabase
                .from('community_members')
                .select('*', { count: 'exact', head: true })
                .eq('community_id', id)
                .eq('status', 'active')

            if (communityData) {
                setCommunity({ ...communityData, member_count: count || 0 })
            }

        } catch (error) {
            console.error('Error loading community:', error)
            setDebugInfo('Error: ' + error.message)
        } finally {
            setLoading(false)
        }
    }

    // ... rest of functions (handleJoin, handlePayment, handleCreatePost, handleLike) remain the same ...

    // For brevity, I'll include the full component at the end

    const canPost = isCreator

    if (loading) {
        return (
            <div className="text-center py-12">
                <div className="text-gray-500">Loading...</div>
            </div>
        )
    }

    if (!community) {
        return (
            <div className="text-center py-12 bg-white rounded-xl shadow-md">
                <div className="text-4xl mb-4">🔍</div>
                <p className="text-gray-500">Community not found</p>
                <Link to="/community" className="text-green-600 hover:underline mt-4 block">
                    ← Back to Communities
                </Link>
            </div>
        )
    }

    return (
        <div>
            {/* Debug Info */}
            <div className="bg-gray-100 p-2 text-xs text-gray-500 mb-4 rounded-lg">
                Debug: {debugInfo} | Posts: {posts.length} | Member: {isMember ? 'Yes' : 'No'} | Creator: {isCreator ? 'Yes' : 'No'}
            </div>

            {/* Community Header */}
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                <div className="flex items-start justify-between">
                    <div>
                        <div className="flex items-center gap-2">
                            <span className="text-3xl">🏛️</span>
                            <h1 className="text-2xl font-bold text-gray-800">{community.name}</h1>
                            {isCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full">Admin</span>}
                            {isMember && !isCreator && <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded-full">✓ Member</span>}
                        </div>
                        <p className="text-gray-500 mt-1">{community.description || 'A private community for football predictions'}</p>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-400">
                            <span>👥 {community.member_count || 0} members</span>
                            <span>📝 {community.post_count || 0} posts</span>
                            <span>💰 R50/month</span>
                        </div>
                        {isCreator && (
                            <div className="mt-2 text-sm text-green-600">
                                💰 You earn R25 per member (50% of R50)
                            </div>
                        )}
                    </div>
                    <div>
                        {isCreator ? (
                            <span className="text-sm bg-yellow-100 text-yellow-800 px-4 py-2 rounded-lg">Creator</span>
                        ) : isMember ? (
                            <span className="text-sm bg-green-100 text-green-800 px-4 py-2 rounded-lg">✓ Member</span>
                        ) : (
                            <button onClick={handleJoin} className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition font-medium">
                                Join R50/month
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {/* Post Form - Only Creator */}
            {canPost && (
                <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                    <form onSubmit={handleCreatePost} className="flex gap-3">
                        <input
                            type="text"
                            value={newPost}
                            onChange={(e) => setNewPost(e.target.value)}
                            placeholder="📢 Share your community announcement..."
                            className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                        />
                        <button
                            type="submit"
                            disabled={submitting || !newPost.trim()}
                            className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50"
                        >
                            {submitting ? 'Posting...' : 'Post'}
                        </button>
                    </form>
                    <p className="text-xs text-gray-400 mt-2">👑 As the creator, your posts are highlighted</p>
                </div>
            )}

            {/* Posts List */}
            {posts.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">📝</div>
                    <p className="text-gray-500">No posts yet</p>
                    <p className="text-sm text-gray-400">
                        {isCreator 
                            ? 'Be the first to share an announcement in your community!' 
                            : isMember 
                                ? 'The creator hasn\'t posted anything yet.'
                                : 'Join the community to see posts.'}
                    </p>
                </div>
            ) : (
                <div className="space-y-4">
                    {posts.map((post) => {
                        const isPostCreator = post.user_id === community.creator_id
                        return (
                            <div key={post.id} className={`bg-white rounded-xl shadow-md p-4 ${isPostCreator ? 'border-2 border-yellow-400' : ''}`}>
                                <div className="flex items-center gap-3 mb-3">
                                    <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                                        {post.profiles?.username?.[0]?.toUpperCase() || 'U'}
                                    </div>
                                    <div>
                                        <div className="font-semibold flex items-center gap-2">
                                            {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                            {isPostCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded-full">👑 Admin</span>}
                                        </div>
                                        <div className="text-xs text-gray-400">@{post.profiles?.username} • {new Date(post.created_at).toLocaleDateString()}</div>
                                    </div>
                                </div>
                                <p className="text-gray-800 mb-3">{post.text}</p>
                                {post.prediction_data && (
                                    <div className="bg-gray-50 rounded-lg p-3 mb-3">
                                        <div className="flex items-center justify-between text-sm">
                                            <span>📊 {post.prediction_data.result || 'Draw'}</span>
                                            <span>🟨{post.prediction_data.yellowCards || 0} 🟥{post.prediction_data.redCards || 0}</span>
                                            <span>🏁{post.prediction_data.corners || 0}</span>
                                        </div>
                                    </div>
                                )}
                                <button 
                                    onClick={() => handleLike(post.id)}
                                    className="flex items-center gap-1 text-sm text-gray-400 hover:text-red-500 transition"
                                >
                                    ❤️ {post.likes_count || 0}
                                </button>
                            </div>
                        )
                    })}
                </div>
            )}

            {/* Payment Modal - same as before */}
            {showPaymentModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6">
                        <h2 className="text-xl font-bold text-gray-800 mb-4">💳 Join {community.name}</h2>
                        <div className="bg-gray-50 rounded-lg p-4 mb-4">
                            <div className="flex justify-between items-center">
                                <span className="text-gray-600">Monthly subscription</span>
                                <span className="font-bold text-xl">R50</span>
                            </div>
                            <div className="flex justify-between items-center text-sm text-gray-500 mt-2 border-t pt-2">
                                <span>👤 Creator earns</span>
                                <span>R25</span>
                            </div>
                            <div className="flex justify-between items-center text-sm text-gray-500">
                                <span>🏢 Platform fee</span>
                                <span>R25</span>
                            </div>
                            <p className="text-xs text-gray-400 mt-2">Cancel anytime.</p>
                        </div>
                        <div className="flex gap-3">
                            <button onClick={() => setShowPaymentModal(false)} className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300">Cancel</button>
                            <button onClick={handlePayment} disabled={submitting} className="flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 disabled:opacity-50">
                                {submitting ? 'Processing...' : 'Pay R50'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
